UPDATE account_status_audience SET sync_status = 1, request_token = #{row.requestToken},
  lease_until = #{row.leaseUntil}, fail_code = NULL, fail_reason = NULL, updated_at = #{row.updatedAt}
WHERE account_id = #{row.accountId} AND updated_at = #{expectedUpdatedAt} AND (sync_status != 1 OR lease_until <= #{row.updatedAt})

UPDATE account_status_audience SET sync_status = #{syncStatus}, jids_json = #{jidsJson},
  contact_num = #{contactNum}, snapshot_version = #{snapshotVersion}, synced_at = #{syncedAt},
  expires_at = #{expiresAt}, fail_code = #{failCode}, fail_reason = #{failReason}, updated_at = #{updatedAt}
WHERE account_id = #{accountId} AND sync_status = 1 AND request_token = #{requestToken}
  AND lease_until > #{updatedAt}
